<script setup lang="ts">
import {onMounted,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {api,type Account} from '../api'
import {money,date,pointsKind,type Member,type Page,type PointEvent,type Consumption} from './customers/types'
import {sourceReason} from './customers/events.mjs'
import './customers/customers.css'
const props=defineProps<{account:Account}>()
const route=useRoute(),member=ref<Member|null>(null),loading=ref(false),error=ref(''),tab=ref('points'),rowsLoading=ref(false),rowsError=ref(''),points=ref<Page<PointEvent>|null>(null),consumption=ref<Page<Consumption>|null>(null),page=ref(1)
let generation=0,rowGeneration=0
async function loadRows(){const seq=++rowGeneration;const memberId=String(route.params.memberId),kind=tab.value;rowsLoading.value=true;rowsError.value='';try{const url=`/members/${memberId}/${kind}?page=${page.value}&pageSize=20`;if(kind==='points'){const r=await api<Page<PointEvent>>(url);if(seq===rowGeneration)points.value=r}else{const r=await api<Page<Consumption>>(url);if(seq===rowGeneration)consumption.value=r}}catch(e){if(seq===rowGeneration){points.value=null;consumption.value=null;rowsError.value=e instanceof Error?e.message:'流水读取失败。'}}finally{if(seq===rowGeneration)rowsLoading.value=false}}
async function load(){const seq=++generation;rowGeneration++;loading.value=true;error.value='';member.value=null;points.value=null;consumption.value=null;page.value=1;try{const r=await api<Member>(`/members/${route.params.memberId}`);if(seq===generation){member.value=r;void loadRows()}}catch(e){if(seq===generation)error.value=e instanceof Error?e.message:'此会员暂不可查看。'}finally{if(seq===generation)loading.value=false}}
function switchTab(t:string){tab.value=t;page.value=1;void loadRows()}
watch(()=>`${props.account.accountId}:${props.account.permissionCodes.join(',')}`,()=>{generation++;rowGeneration++;member.value=null;points.value=null;consumption.value=null;loading.value=false;rowsLoading.value=false;if(props.account.permissionCodes.includes('member.read'))void load()});
onMounted(()=>void load());watch(()=>route.params.memberId,()=>void load())
</script>
<template><section class="page-content customer-page"><header class="page-heading"><div><RouterLink to="/members" class="text-link">返回会员列表</RouterLink><h1>会员详情</h1><p class="customer-id">{{route.params.memberId}}</p></div><button class="secondary-button" :disabled="loading||rowsLoading" @click="load">刷新权益</button></header><p v-if="loading" role="status">正在读取会员权益…</p><div v-else-if="error" class="notice error" role="alert">{{error}} <button class="text-button" @click="load">重试</button></div><template v-else-if="member"><section class="panel customer-summary"><div><p class="eyebrow">当前等级</p><h2>{{member.grade.name}}</h2><p>{{member.enabled?'账号正常':'账号已停用'}} · 等级生效 {{date(member.gradeEffectiveAt)}}</p></div><div><span>累计有效消费</span><strong>{{money(member.effectiveSpendFen)}}</strong><small>根据已结算消费与退款累计调整</small></div></section><section class="customer-stats"><article><span>可用积分</span><strong>{{member.points.availablePoints}}</strong></article><article><span>已结算余额</span><strong>{{member.points.settledPoints}}</strong></article><article><span>订单冻结</span><strong>{{member.points.frozenPoints}}</strong></article><article><span>积分欠额</span><strong :class="{'error':member.points.debtPoints>0}">{{member.points.debtPoints}}</strong></article></section><p class="customer-note">冻结积分暂不可用；奖励退款扣回可形成欠额，后续新增积分优先抵扣欠额。会员已激活等级规则修订 {{member.gradePolicyRevision}}，当前运营规则修订 {{member.ruleRevision}}。</p><p v-if="member.points.expiringPoints" class="notice">{{member.points.expiringPoints}} 积分将在 {{date(member.points.nextExpiryAt)}} 到期。</p><p v-if="member.points.expiredPendingPoints" class="notice">{{member.points.expiredPendingPoints}} 积分已到期、待到期结算，不计入可用积分。</p><section class="panel customer-ledger"><div class="customer-tabs" role="group" aria-label="流水类型"><button :class="tab==='points'?'primary-button':'secondary-button'" @click="switchTab('points')">积分明细</button><button :class="tab==='consumption'?'primary-button':'secondary-button'" @click="switchTab('consumption')">消费与等级变化</button></div><p v-if="rowsLoading" role="status">正在读取明细…</p><div v-else-if="rowsError" class="error notice" role="alert">{{rowsError}} <button class="text-button" @click="loadRows">重试</button></div><template v-else><div v-if="tab==='points'&&points?.items.length" class="table-wrap" tabindex="0" aria-label="积分流水，可横向滚动"><table><thead><tr><th>时间</th><th>类型</th><th>积分数量</th><th>余额</th><th>关联订单／来源</th><th>有效期</th></tr></thead><tbody><tr v-for="r in points.items" :key="r.id"><td>{{date(r.createdAt)}}</td><td>{{pointsKind(r.kind)}}<small>{{r.effect==='FREEZE'?'冻结变动':r.effect==='RELEASE'?'释放冻结':'余额变动'}}</small></td><td>{{r.amount}}</td><td>{{r.balance??'—'}}</td><td class="customer-id"><RouterLink v-if="r.orderId&&account.permissionCodes.includes('order.read')" :to="`/orders/${r.orderId}`" class="text-link">{{r.orderId}}</RouterLink><span v-else>{{r.orderId||'—'}}</span><small>{{sourceReason(r.sourceRef)}}</small></td><td>{{date(r.expiresAt)}}</td></tr></tbody></table></div><div v-else-if="tab==='consumption'&&consumption?.items.length" class="table-wrap" tabindex="0" aria-label="消费流水，可横向滚动"><table><thead><tr><th>时间</th><th>消费变动</th><th>累计有效消费</th><th>等级变化</th><th>来源</th></tr></thead><tbody><tr v-for="r in consumption.items" :key="r.id"><td>{{date(r.createdAt)}}</td><td>{{money(r.amountFen)}}</td><td>{{money(r.balanceFen)}}</td><td>{{r.gradeBefore?.name||'—'}} → {{r.gradeAfter?.name||'—'}}</td><td class="customer-id">{{r.orderId}}<small>{{sourceReason(r.sourceRef)}}</small></td></tr></tbody></table></div><p v-else class="empty-state">暂无{{tab==='points'?'积分':'消费'}}明细。</p><div class="customer-pagination"><span>共 {{(tab==='points'?points:consumption)?.pagination.total||0}} 条 · 第 {{page}} 页</span><div><button class="secondary-button" :disabled="page<=1" @click="page--;loadRows()">上一页</button><button class="secondary-button" :disabled="page*20>=((tab==='points'?points:consumption)?.pagination.total||0)" @click="page++;loadRows()">下一页</button></div></div></template></section></template></section></template>
